using System;using System.Data;using System.Linq;using System.IO;
namespace Videira {static class BatchConfirmTests {
 static void Check(bool b,string m){if(!b)throw new Exception("Lote: "+m);}
 public static void Run(){var db=new Store(Path.Combine(Environment.CurrentDirectory,"work","Batch-"+Guid.NewGuid()));db.SetupStoneRates();db.ImportPortfolio();var rows=db.Data.Tables["Mercado"].AsEnumerable().Take(3).ToArray();int count=db.ConfirmMarketProducts(rows);Check(count==3,"três confirmados");for(int i=0;i<3;i++){var p=db.Data.Tables["Produtos"].Rows.Find(rows[i]["Produto"]);Check(p["Código"].ToString()==(i+1).ToString()&&(decimal)p["Estoque"]==1&&(bool)p["Confirmado"],"códigos e uma unidade");}Check(db.Data.Tables["Movimentos"].Rows.Count==3,"movimentação inicial");Check(db.ConfirmMarketProducts(rows)==0&&db.Data.Tables["Movimentos"].Rows.Count==3,"repetição não duplica estoque");db=new Store(db.Root);Check(db.MarketView(true).Rows.Count==134,"somem do mercado ao reabrir");var invalid=db.Data.Tables["Mercado"].AsEnumerable().Skip(3).Take(2).ToArray();db.Data.Tables["Produtos"].Rows.Find(invalid[1]["Produto"])["Taxa padrão"]="Taxa inexistente";bool failed=false;try{db.ConfirmMarketProducts(invalid);}catch{failed=true;}Check(failed,"lote inválido rejeitado");Check(!(bool)db.Data.Tables["Produtos"].Rows.Find(invalid[0]["Produto"])["Confirmado"]&&db.Data.Tables["Movimentos"].Rows.Count==3,"rollback sem confirmação parcial");File.AppendAllText(Path.Combine(Environment.CurrentDirectory,"work","test-result.txt"),"\r\nPASS 3.6: confirmar lote, códigos 1/2/3, estoque inicial 1, movimento, idempotência, persistência e rollback integral.");}
}}
